export const HEBREW_FONTS: string[] = ["Assistant", "Frank Ruhl Libre", "Heebo", "Rubik", "Secular One", "Suez One"];

const loaded = new Set<string>();
/** Registers every face of a bundled family (once). Returns the CSS family name. Unknown names fall back to Heebo. */
export const useBundledFont = (family: string): string => {
	const fam = FONT_FILES[family] ? family : 'Heebo';
	if (!loaded.has(fam)) {
		loaded.add(fam);
		for (const f of FONT_FILES[fam] ?? []) {
			loadFont({family: fam, url: f.url, weight: f.weight, style: f.style, unicodeRange: f.unicodeRange || undefined, format: 'woff2'}).catch(() => undefined);
		}
	}
	return fam;
};
